@Test
public void testRuleMatches() {
    Rule rule = new AndRule(new AlwaysTrueRule(), new AlwaysTrueRule());
    Assert.assertTrue(rule.ruleMatches(null));
    rule = new AndRule(new AlwaysTrueRule(), new NotRule(new AlwaysTrueRule()));
    Assert.assertFalse(rule.ruleMatches(null));
    rule = new AndRule(new NotRule(new AlwaysTrueRule()), new AlwaysTrueRule());
    Assert.assertFalse(rule.ruleMatches(null));
    rule = new AndRule(new NotRule(new AlwaysTrueRule()), new NotRule(new AlwaysTrueRule()));
    Assert.assertFalse(rule.ruleMatches(null));
}

